const fs = require('fs');

const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
const n = data[0];
const weights = data.slice(1, n + 1);
const target = weights.reduce((sum, weight) => sum + weight, 0) / n;

console.log(weights.map(weight => target - weight).join('\n'));
